input.command:
$roots = @(
  "$env:LOCALAPPDATA\OpenAI",
  "$env:APPDATA\OpenAI",
  "$env:LOCALAPPDATA\ChatGPT",
  "$env:APPDATA\ChatGPT",
  "$env:LOCALAPPDATA\Packages",
  "$env:APPDATA\Codex",
  "$env:LOCALAPPDATA\Codex"
)
foreach ($r in $roots) {
  Write-Output "PATH $r exists=$(Test-Path -LiteralPath $r)"
  if (Test-Path -LiteralPath $r) {
    Get-ChildItem -LiteralPath $r -Force -ErrorAction SilentlyContinue | Select-Object -First 20 Name, Mode | ForEach-Object { "  $($_.Mode) $($_.Name)" }
  }
}
Write-Output "---packages chatgpt---"
Get-ChildItem -LiteralPath "$env:LOCALAPPDATA\Packages" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match "OpenAI|ChatGPT|Codex" } | Select-Object -ExpandProperty Name

Get-ChildItem -LiteralPath "$env:LOCALAPPDATA\Packages" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match "OpenAI|ChatGPT|openai" } | Select-Object Name, FullName
Write-Output "--- start menu / programs ---"
@(
  "$env:LOCALAPPDATA\Programs",
  "$env:PROGRAMFILES",
  "${env:PROGRAMFILES(X86)}"
) | ForEach-Object {
  if (Test-Path -LiteralPath $_) {
    Get-ChildItem -LiteralPath $_ -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match "ChatGPT|OpenAI|Codex" } | ForEach-Object { $_.FullName }
  }
}
Write-Output "--- roaming electron chatgpt ---"
Get-ChildItem -LiteralPath "$env:APPDATA" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match "chat|openai|gpt" } | Select-Object Name

python -c 'import sqlite3,os; from pathlib import Path; p=Path(os.environ["USERPROFILE"])/".codex"/"thread_history_1.sqlite"; con=sqlite3.connect("file:"+str(p).replace("\\","/")+"?mode=ro", uri=True); print("size", p.stat().st_size); names=[r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type=\"table\"")]; print("tables", names); 
for name in names:
    n=con.execute("SELECT COUNT(*) FROM \""+name+"\"").fetchone()[0]; cols=[r[1] for r in con.execute("PRAGMA table_info(\""+name+"\")")]; print(name, n, ",".join(cols)[:180])
con.close()'

$candidates = @(
  "$env:LOCALAPPDATA\Google\Chrome\User Data",
  "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data",
  "$env:LOCALAPPDATA\Microsoft\Edge\User Data",
  "$env:APPDATA\Mozilla\Firefox\Profiles"
)
foreach ($c in $candidates) {
  Write-Output "EXISTS $(Test-Path -LiteralPath $c) $c"
}
Write-Output "--- chatgpt host folders (names only) ---"
$roots = @(
  "$env:LOCALAPPDATA\Google\Chrome\User Data\Default",
  "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\Default",
  "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default"
)
foreach ($r in $roots) {
  if (-not (Test-Path -LiteralPath $r)) { continue }
  Write-Output "ROOT $r"
  foreach ($sub in @("IndexedDB","Local Storage","Service Worker","Cache","Code Cache","GPUCache")) {
    $p = Join-Path $r $sub
    if (Test-Path -LiteralPath $p) {
      $hits = Get-ChildItem -LiteralPath $p -ErrorAction SilentlyContinue | Where-Object { $_.Name -match "chatgpt|openai" }
      Write-Output "  $sub chatgpt/openai name hits=$($hits.Count)"
      $hits | Select-Object -First 8 -ExpandProperty Name
    }
  }
}

$paths = @(
  "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\IndexedDB\https_chatgpt.com_0.indexeddb.leveldb",
  "$env:LOCALAPPDATA\Google\Chrome\User Data\Default\IndexedDB\https_chatgpt.com_0.indexeddb.blob",
  "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\Default\IndexedDB\https_chatgpt.com_0.indexeddb.leveldb",
  "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\Default\IndexedDB\https_chatgpt.com_0.indexeddb.blob",
  "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\IndexedDB\https_chatgpt.com_0.indexeddb.leveldb",
  "$env:USERPROFILE\.codex\sessions",
  "$env:USERPROFILE\.codex\archived_sessions",
  "$env:USERPROFILE\.codex\thread_history_1.sqlite",
  "$env:USERPROFILE\.codex\state_5.sqlite",
  "$env:LOCALAPPDATA\Packages\OpenAI.Codex_2p2nqsd0c76g0\LocalCache\Local\Codex\Logs"
)
foreach ($p in $paths) {
  if (Test-Path -LiteralPath $p) {
    $item = Get-Item -LiteralPath $p
    if ($item.PSIsContainer) {
      $sum = (Get-ChildItem -LiteralPath $p -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum)
      "DIR bytes=$($sum.Sum) files=$($sum.Count) $p"
    } else {
      "FILE bytes=$($item.Length) $p"
    }
  } else {
    "MISSING $p"
  }
}
